41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    /**
62	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
63	     * at least one dot and no whitespace on either side.
64	     */
65	    private static final Pattern EMAIL_PATTERN =
66	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        validateRequiredFields(ownerFieldsDto);
115	        normalizeTelephone(ownerFieldsDto);
116	        rejectDuplicateTelephone(ownerFieldsDto);
117	        normalizeEmail(ownerFieldsDto);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
130	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
131	        if (currentOwner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        currentOwner.setAddress(ownerFieldsDto.getAddress());
135	        currentOwner.setCity(ownerFieldsDto.getCity());
136	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
137	        currentOwner.setLastName(ownerFieldsDto.getLastName());
138	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
139	        normalizeEmail(ownerFieldsDto);
140	        currentOwner.setEmail(ownerFieldsDto.getEmail());
141	        this.clinicService.saveOwner(currentOwner);
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Transactional
147	    @Override
148	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        this.clinicService.deleteOwner(owner);
154	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        HttpHeaders headers = new HttpHeaders();
165	        Pet pet = petMapper.toPet(petFieldsDto);
166	        owner.setId(ownerId);
167	        pet.setOwner(owner);
168	        pet.getType().setName(null);
169	        this.clinicService.savePet(pet);
170	        PetDto petDto = petMapper.toPetDto(pet);
171	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
172	            .buildAndExpand(pet.getId()).toUri());
173	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner != null) {
181	            Pet currentPet = this.clinicService.findPetById(petId);
182	            if (currentPet != null) {
183	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
184	                currentPet.setName(petFieldsDto.getName());
185	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
186	                this.clinicService.savePet(currentPet);
187	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	            }
189	        }
190	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
196	        HttpHeaders headers = new HttpHeaders();
197	        Visit visit = visitMapper.toVisit(visitFieldsDto);
198	        Pet pet = new Pet();
199	        pet.setId(petId);
200	        visit.setPet(pet);
201	        this.clinicService.saveVisit(visit);
202	        VisitDto visitDto = visitMapper.toVisitDto(visit);
203	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
204	            .buildAndExpand(visit.getId()).toUri());
205	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
206	    }
207	
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner != null) {
214	            Pet pet = owner.getPet(petId);
215	            if (pet != null) {
216	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
217	            }
218	        }
219	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	    }
221	
222	    /**
223	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
224	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
225	     * does not catch). The names of all offending fields are collected so the caller receives a
226	     * 400 response whose {@code errors} array lists each one.
227	     */
228	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
229	        List<String> missingFields = new ArrayList<>();
230	        if (isBlank(ownerFieldsDto.getFirstName())) {
231	            missingFields.add("firstName");
232	        }
233	        if (isBlank(ownerFieldsDto.getLastName())) {
234	            missingFields.add("lastName");
235	        }
236	        if (isBlank(ownerFieldsDto.getAddress())) {
237	            missingFields.add("address");
238	        }
239	        if (isBlank(ownerFieldsDto.getCity())) {
240	            missingFields.add("city");
241	        }
242	        if (isBlank(ownerFieldsDto.getTelephone())) {
243	            missingFields.add("telephone");
244	        }
245	        if (!missingFields.isEmpty()) {
246	            throw new InvalidOwnerFieldsException(missingFields);
247	        }
248	    }
249	
250	    private static boolean isBlank(String value) {
251	        return value == null || value.trim().isEmpty();
252	    }
253	
254	    /**
255	     * Normalizes an owner's {@code telephone} on create by removing every non-digit character and
256	     * requiring exactly ten digits to remain. The stripped, 10-digit value is written back onto the
257	     * request so it is what gets stored and returned. Any value that does not reduce to exactly ten
258	     * digits is rejected with a 400 response whose {@code errors} array names {@code telephone}.
259	     */
260	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
261	        String telephone = ownerFieldsDto.getTelephone();
262	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
263	        if (digits.length() != 10) {
264	            throw new InvalidOwnerFieldsException(List.of("telephone"));
265	        }
266	        ownerFieldsDto.setTelephone(digits);
267	    }
268	
269	    /**
270	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
271	     * The incoming value has already been reduced to its 10-digit normal form by
272	     * {@link #normalizeTelephone}; each existing owner's stored telephone is normalized the same
273	     * way (stripping non-digit characters) before comparison so differing input formats still
274	     * collide. A match results in a 409 response naming {@code telephone}.
275	     */
276	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
277	        String telephone = ownerFieldsDto.getTelephone();
278	        for (Owner existing : this.clinicService.findAllOwners()) {
279	            if (telephone.equals(normalizeDigits(existing.getTelephone()))) {
280	                throw new DuplicateOwnerTelephoneException(telephone);
281	            }
282	        }
283	    }
284	
285	    private static String normalizeDigits(String telephone) {
286	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
287	    }
288	
289	    /**
290	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
291	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
292	     * written back onto the request so that is what gets stored and returned. A present but invalid
293	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
294	     */
295	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
296	        String email = ownerFieldsDto.getEmail();
297	        if (email == null) {
298	            return;
299	        }
300	        String trimmed = email.trim();
301	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
302	            throw new InvalidOwnerFieldsException(List.of("email"));
303	        }
304	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
305	    }
306	}
